from .facade import Client, DEFAULT_ALIAS


class browser_server(object):  # noqa

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._client = Client()

    def setup_client(self, bts_host='192.168.255.1', bts_port=15003, enable_extra_log=False):
        """
        Set up the library.

        .. note::

            Within the setup, the HW version of MSM and ESM (if available) is automatically detected. However,
            for this detection to work properly, it is required that SSH connection to BTS is enabled, in particular,
            that ``systemAcctPermEnable`` is set to ``false`` in SCF.


        :param str bts_host: BTS ip address (192.168.255.1 is default)
        :param str bts_port: BTS port to connect to (15003 is default)
        :param str enable_extra_log: (Optional) If set to `${True}`, a special library log will be collected
            in ~/taf.sbts.browser_server_logs

        .. code-block:: robotframework

            browser_server.setup_client
            browser_server.setup_client    bts_host=192.168.255.1    bts_port=15004
            browser_server.setup_client    enable_extra_log=${False}

        """
        self._client.set_up(bts_host=bts_host, bts_port=bts_port, enable_extra_log=enable_extra_log)

    def teardown_client(self):
        """
        Tear down the library.

        """
        self._client.tear_down()

    def get_rtt_value(self, cell_id):
        """
        Initialize IR measurements and return the round-trip time value (RTT)

        :param (int|str) cell_id: WCDMA cell id
        return: RTT value
        """
        return self._client.get_rtt_value(cell_id)

    def start_hsupa_l2_trace(self, cell_id, trace_alias=DEFAULT_ALIAS):
        """
         Start collecting given trace

         .. note::
             Must go in pair with ``Stop Trace`` or ``Stop All Traces``

        :param (int|str) cell_id: WCDMA cell id
        :param str trace_alias: alias for trace collector
         """
        self._client.start_hsupa_l2_trace(cell_id, trace_alias)

    def start_cell_throughput(self, cell_id, trace_alias=DEFAULT_ALIAS):
        """
        Start cell throughput in UL.

        .. note::
            Must go in pair with ``Stop Trace`` or ``Stop All Traces``

        :param (int|str) cell_id: WCDMA cell id
        :param str trace_alias: alias for trace collector

        """
        self._client.start_cell_throughput(cell_id, trace_alias)

    def stop_trace(self, trace_alias=DEFAULT_ALIAS):
        """
        Stop collecting traces specified by ``trace_alias``.

        :param str trace_alias: alias for trace collector
        """
        self._client.stop_trace(trace_alias=trace_alias)

    def save_trace(self, output_path, trace_alias=DEFAULT_ALIAS, as_zip=True):
        """
        Save file with traces specified by ``trace_alias``.

        :param str output_path: path where TXT or ZIP file with traces will be saved
        :param str trace_alias: alias for trace collector
        :param bool as_zip: True (default) or False
        return: path to saved file
        """
        return self._client.save_trace(output_path, trace_alias=trace_alias, as_zip=as_zip)

    def stop_and_save_trace(self, output_path, trace_alias=DEFAULT_ALIAS, as_zip=True):
        """
        A convenience method combining the two actions.

        :param str output_path: path where TXT or ZIP file with traces will be saved
        :param str trace_alias: alias for trace collector
        :param bool as_zip: True (default) or False
        """
        self._client.stop_trace(trace_alias=trace_alias)
        return self._client.save_trace(output_path, trace_alias=trace_alias, as_zip=as_zip)
